import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['RSPP-A','RSPP-AGG']
EA(K,'ZR95','Rischi emergenti',[LB("Laboratorio · Il piano per il caldo estremo","Prepari il piano per le ondate di calore di un’impresa edile con cantieri all’aperto.",[
  ["Cantieri","3 cantieri stradali ed edili, 35 operai"],["Problemi","due malori da calore l’estate scorsa; lavori in copertura"],["Strumenti","bollettini e mappe del rischio calore; ordinanze regionali nei giorni critici"]],[
  ("Quali fonti di informazione usi e come?",6,"Bollettini e previsioni del rischio calore consultati ogni giorno nei mesi estivi; ordinanze regionali che possono vietare il lavoro nelle ore più calde; misure in cantiere, ad esempio con l’indice WBGT dove utile.",["Ho previsto il monitoraggio quotidiano","Ho considerato le ordinanze"]),
  ("Quali misure organizzative prevedi?",8,"Spostamento delle attività pesanti al mattino presto; sospensione nelle ore più calde nei giorni a rischio alto; pause in zone ombreggiate; rotazione; acclimatamento graduale dei nuovi e di chi rientra; lavoro in coppia.",["Ho previsto orari e sospensioni","Ho previsto pause e acclimatamento"],None,120),
  ("Quali misure per le persone e le emergenze?",7,"Acqua fresca disponibile; indumenti leggeri e protezione del capo; formazione su sintomi del colpo di calore; procedura di primo soccorso con chiamata al 112; attenzione ai lavoratori con condizioni di salute particolari indicate dal medico competente.",["Ho previsto acqua e indumenti","Ho previsto formazione e primo soccorso"]),
  ("Come documenti e verifichi il piano?",6,"Integrazione nel DVR e nei POS; registro dei giorni a rischio e delle misure adottate; analisi dei malori; riesame a fine estate con RLS e medico competente.",["Ho previsto DVR e POS","Ho previsto il riesame"])],
 "Nel laboratorio prepari il piano per le ondate di calore di un’impresa edile: fonti di informazione, misure organizzative e personali, documentazione. Confronta ogni risposta con la soluzione di riferimento.","Art. 28 D.lgs. 81/2008 · ordinanze regionali sul caldo")])
EA(K,'ZR96','Sistemi di gestione: novità',[CL("Quale punto della ISO 45001?","Seleziona un requisito, poi il punto della norma.",["4 · Contesto","5 · Leadership e partecipazione","6 · Pianificazione","8 · Attività operative","9 · Valutazione delle prestazioni","10 · Miglioramento"],[
 ["Determinare i fattori interni ed esterni, incluso il cambiamento climatico",0,"Punto 4.1."],["Consultazione e partecipazione dei lavoratori",1,"Punto 5.4."],
 ["Valutare rischi e opportunità e pianificare le azioni",2,"Punto 6.1."],["Gestire gli appalti e il cambiamento",3,"Punto 8.1."],
 ["Audit interno e riesame della direzione",4,"Punti 9.2 e 9.3."],["Incidenti, non conformità e azioni correttive",5,"Punto 10.2."]],
 "Sei requisiti del sistema di gestione. Collocali nel punto della UNI EN ISO 45001.","UNI EN ISO 45001:2023")])
EA(K,'ZR97','Esempio applicativo: l’albero dei guasti',[LB("Laboratorio · L’albero dei guasti","Costruisci un semplice albero dei guasti per l’evento «avvio improvviso della pressa durante la manutenzione».",[
  ["Cause possibili","manutentore non applica il lucchetto (probabilità annua stimata 0,05); collega avvia la pressa senza controllo (0,02); guasto del sezionatore (0,001)"],["Logica","l’evento accade se il sezionatore guasta, oppure se manca il lucchetto e contemporaneamente un collega avvia la pressa"]],[
  ("Disegna la logica con porte E e O.",7,"Evento di vertice con porta O. Ramo 1: guasto del sezionatore. Ramo 2: porta E tra mancata applicazione del lucchetto e avvio da parte del collega.",["Ho usato una porta O al vertice","Ho usato una porta E nel ramo 2"]),
  ("Calcola la probabilità dell’evento di vertice.",7,"Ramo 2: 0,05 × 0,02 = 0,001. Vertice, con eventi rari: circa 0,001 + 0,001 = 0,002 l’anno.",["Ho moltiplicato nella porta E","Ho sommato nella porta O"]),
  ("Quale intervento riduce di più la probabilità?",7,"I due rami pesano allo stesso modo. Una procedura di blocco con lucchetti personali e verifica dell’energia zero riduce il ramo 2; un sezionatore affidabile con manutenzione e prova periodica riduce il ramo 1. Servono entrambi.",["Ho confrontato i rami","Ho proposto interventi su entrambi"]),
  ("Quali limiti ha l’analisi?",5,"Le probabilità sono stime; possono esistere cause comuni che rendono gli eventi non indipendenti, come la fretta; l’albero va aggiornato con dati di campo.",["Ho indicato stime e dipendenze","Ho previsto l’aggiornamento"])],
 "Nel laboratorio costruisci un albero dei guasti per l’avvio improvviso di una pressa: logica, calcolo della probabilità, interventi e limiti. Confronta ogni risposta con la soluzione di riferimento.","CEI EN 61025 · UNI ISO 31010")])
EA(K,'ZR98','Bow-tie: le barriere preventive e mitigative',[LB("Laboratorio · Il bow-tie dello sversamento","Costruisci il diagramma bow-tie per l’evento «perdita di contenimento di un serbatoio di acido».",[
  ["Serbatoio","acido cloridrico in un’area di stoccaggio"],["Minacce","corrosione, urto di un carrello, sovrariempimento"],["Conseguenze","ustioni a lavoratori, vapori tossici, contaminazione del suolo"]],[
  ("Individua una barriera preventiva per ciascuna minaccia.",7,"Corrosione: ispezioni e spessimetrie periodiche. Urto: barriere fisiche e percorsi separati per i carrelli. Sovrariempimento: allarme e blocco di alto livello.",["Ho associato una barriera a ogni minaccia"]),
  ("Individua le barriere mitigative per le conseguenze.",7,"Bacino di contenimento; doccia e lavaocchi; procedura di emergenza con DPI; neutralizzazione e materiali assorbenti; sistema di rilevazione dei vapori.",["Ho previsto contenimento e presidi","Ho previsto la procedura di emergenza"]),
  ("Come verifichi che le barriere funzionino?",7,"Ogni barriera ha un responsabile, un controllo periodico e un indicatore: ad esempio prove dell’allarme di livello, verifica del bacino, esercitazioni di sversamento.",["Ho assegnato responsabili e controlli","Ho previsto indicatori"])],
 "Nel laboratorio costruisci il diagramma bow-tie per la perdita di un serbatoio di acido: barriere preventive, mitigative e verifica della loro efficacia. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 31010")])
EA(K,'ZR99','Condurre un audit: la UNI EN ISO 19011',[LB("Laboratorio · Pianificare e condurre un audit interno","Pianifichi l’audit interno del sistema di gestione della sicurezza di uno stabilimento di 150 lavoratori.",[
  ["Ambito","produzione, manutenzione, magazzino, appalti"],["Tempo","2 giornate"],["Auditor","tu e un collega di un altro stabilimento"]],[
  ("Scrivi il programma dell’audit.",7,"Obiettivi e criteri: requisiti della ISO 45001 e obblighi di legge; ambito: le quattro aree; calendario con riunione di apertura, interviste, sopralluoghi ed esame dei documenti per area; riunione di chiusura.",["Ho definito obiettivi, criteri e ambito","Ho previsto apertura e chiusura"]),
  ("Quali evidenze raccogli negli appalti?",7,"DUVRI e loro aggiornamento; verifica dell’idoneità degli appaltatori; permessi di lavoro; verbali delle riunioni di coordinamento; interviste a preposti delle imprese esterne; osservazione di un lavoro in corso.",["Ho previsto documenti e interviste","Ho previsto l’osservazione sul campo"]),
  ("Come formuli una non conformità?",7,"Con requisito, evidenza oggettiva e scostamento: ad esempio, requisito 8.1.4.2; evidenza: due permessi di lavoro a caldo senza firma del preposto; non conformità: il controllo dei lavori a caldo non è applicato in modo sistematico.",["Ho indicato requisito ed evidenza","Ho formulato lo scostamento"]),
  ("Come assicuri l’imparzialità?",5,"Auditor che non verificano il proprio lavoro; collega di un altro stabilimento; decisioni basate su evidenze; riservatezza.",["Ho garantito indipendenza","Ho basato le conclusioni sulle evidenze"])],
 "Nel laboratorio pianifichi e conduci un audit interno secondo la UNI EN ISO 19011: programma, evidenze sugli appalti, formulazione delle non conformità e imparzialità. Confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 19011 · UNI EN ISO 45001")])
EA(K,'ZS01','Arresto caduta: tirante d’aria, ancoraggi e soccorso',[LB("Laboratorio · Il tirante d’aria","Verifichi un sistema di arresto caduta per un lavoro su un soppalco alto 5 metri.",[
  ["Sistema","cordino da 2 m con assorbitore di energia; ancoraggio a livello dei piedi del lavoratore"],["Dati del fabbricante","allungamento massimo dell’assorbitore 1,75 m"],["Ipotesi","distanza tra punto di attacco dell’imbracatura e piedi 1,5 m; margine di sicurezza 1 m"]],[
  ("Calcola il tirante d’aria necessario.",7,"Con ancoraggio ai piedi la caduta libera è di circa 2 m più la distanza dell’attacco: nel calcolo semplificato, lunghezza del cordino 2 m + allungamento 1,75 m + distanza attacco-piedi 1,5 m + margine 1 m = 6,25 m, oltre a eventuali spostamenti dell’ancoraggio.",["Ho sommato le componenti","Ho ottenuto circa 6,25 m"]),
  ("Il sistema è adatto ai 5 m disponibili?",6,"No: il tirante necessario supera l’altezza disponibile, il lavoratore urterebbe il suolo. Servono ancoraggio più alto, cordino più corto, dispositivo retrattile adatto o sistema di trattenuta che impedisce di raggiungere il bordo.",["Ho concluso che non è adatto","Ho proposto alternative"]),
  ("Che cosa prevede il piano di soccorso?",7,"Recupero rapido della persona sospesa per evitare la sindrome da sospensione inerte; attrezzatura di soccorso disponibile; persone addestrate presenti; esercitazioni periodiche.",["Ho previsto il recupero rapido","Ho previsto addestramento e attrezzature"])],
 "Nel laboratorio verifichi un sistema di arresto caduta su un soppalco di cinque metri: tirante d’aria, adeguatezza del sistema e piano di soccorso. Confronta ogni risposta con la soluzione di riferimento.","Artt. 111 e 115 D.lgs. 81/2008 · UNI EN 363 · UNI EN 355")])
EA(K,'ZS02','Lavori elettrici e lavori in prossimità di linee elettriche',[LB("Laboratorio · Organizzare un lavoro elettrico","Organizzi la sostituzione di un interruttore in un quadro di distribuzione di uno stabilimento.",[
  ["Quadro","bassa tensione, alimenta due reparti"],["Squadra","un elettricista esperto e un aiutante non formato"],["Vincolo","la produzione vorrebbe evitare il fuori servizio"]],[
  ("Quale modalità di lavoro scegli e perché?",6,"Lavoro fuori tensione come regola: le esigenze produttive non giustificano il lavoro sotto tensione, che è ammesso solo nei casi e con le condizioni previste dalle norme e da personale idoneo.",["Ho scelto il lavoro fuori tensione","Ho motivato la scelta"]),
  ("Quali sono i passaggi per mettere fuori tensione in sicurezza?",8,"Individuazione del circuito; sezionamento; blocco e cartellonistica contro la richiusura; verifica dell’assenza di tensione; messa a terra e in cortocircuito se necessaria; protezione verso parti vicine in tensione; consegna dell’impianto con documento.",["Ho elencato i passaggi","Ho incluso blocco e verifica di assenza di tensione"],None,120),
  ("Che ruolo può avere l’aiutante?",6,"Senza formazione e qualifica non può operare sulle parti elettriche: può svolgere compiti non elettrici sotto supervisione. Le qualifiche di persona esperta o avvertita sono attribuite dal datore di lavoro dopo la formazione prevista.",["Ho limitato i compiti dell’aiutante","Ho citato le qualifiche"])],
 "Nel laboratorio organizzi la sostituzione di un interruttore in un quadro: modalità di lavoro, passaggi di messa fuori tensione e ruolo dell’aiutante. Confronta ogni risposta con la soluzione di riferimento.","Artt. 82-83 D.lgs. 81/2008 · CEI EN 50110-1 · CEI 11-27")])
EA(K,'ZS03','Ambienti confinati: il nuovo corso',[SC("Il corso per gli ambienti confinati","Un’impresa di spurghi deve formare 8 operatori che entrano in fosse e cisterne.",[
 ("Quale corso prevede l’Accordo 2025?",[["Un corso specifico per ambienti confinati o sospetti di inquinamento di 12 ore, con parte pratica",True,"Corretto."],["Il solo corso generale di 4 ore",False,"Non basta."],["Nessun corso specifico",False,"L’Accordo lo prevede."]]),
 ("Che cosa deve comprendere la parte pratica?",[["Uso di rilevatori di gas, DPI respiratori, sistemi di recupero e simulazione del soccorso",True,"Corretto."],["Solo un video",False,"Serve pratica reale."],["La guida del mezzo",False,"Non è pertinente."]]),
 ("La formazione basta per entrare?",[["No: servono anche la procedura di lavoro, le misure dell’atmosfera, il permesso e il soccorso organizzato",True,"Corretto."],["Sì",False,"La formazione è uno degli elementi."],["Sì, se c’è un collega fuori",False,"Il soccorso deve essere organizzato e attrezzato."]])],
 "Il corso di dodici ore con parte pratica è necessario ma non sufficiente: ogni ingresso richiede procedura, misure, permesso e soccorso organizzato.","Formare operatori che entrano in cisterne. Definisci il percorso.","Accordo 17 aprile 2025 · D.P.R. 177/2011")])
EA(K,'ZS04','Modelli semplificati per le PMI e asseverazione',[SC("L’asseverazione del modello","Una PMI edile ha adottato un modello organizzativo semplificato e chiede che cosa le porti l’asseverazione.",[
 ("Chi può asseverare l’adozione e l’efficace attuazione del modello?",[["Gli organismi paritetici, secondo quanto previsto dall’art. 51",True,"Corretto."],["Solo un notaio",False,"Non è previsto."],["L’ASL",False,"Non è un’asseverazione dell’ASL."]]),
 ("Quale effetto ha l’asseverazione?",[["Gli organi di vigilanza possono tenerne conto nella programmazione delle proprie attività",True,"Corretto: art. 51, comma 3-bis."],["Esenta da ogni controllo",False,"Non esenta."],["Sostituisce il DVR",False,"Non lo sostituisce."]]),
 ("Il modello semplificato garantisce l’esimente 231?",[["Può contribuire, ma conta l’efficace attuazione, che il giudice valuta in concreto",True,"Corretto."],["Sì, automaticamente",False,"Non c’è automatismo."],["No, mai",False,"Può avere valore esimente."]])],
 "L’asseverazione degli organismi paritetici dà visibilità al modello presso la vigilanza, ma l’esimente dipende sempre dall’efficace attuazione.","Una PMI chiede dell’asseverazione. Rispondi con precisione.","Artt. 30 e 51 D.lgs. 81/2008 · D.M. 13 febbraio 2014")])
EA(K,'ZS05','Esercitazione 4 · Ingresso in una vasca',[AP("Sistemi di gestione e lavori ad alto rischio nella tua realtà","Verifica come sono gestiti i lavori ad alto rischio.",["Permessi di lavoro per lavori a caldo","Procedura per ambienti confinati","Procedura di blocco delle energie","Sistemi anticaduta con piano di soccorso","Qualifiche per lavori elettrici","Audit interni programmati"],"Il lavoro ad alto rischio meno controllato e la prima azione","Es.: lavori in copertura senza piano di soccorso",
  "Verifica come sono gestiti i lavori ad alto rischio e indica quello meno controllato con la prima azione.",3)])
